{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-05",
  "sketch": {
    "components": ["Driver mobile app", "GPS location sender", "Map endpoint", "Customer live map view"],
    "dataStores": ["Driver location store"],
    "externalServices": [],
    "trustBoundaries": ["Driver phone to backend", "Backend to customer app"],
    "dataClasses": ["pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Anyone who guesses a delivery id can see any driver's live location and phone number",
      "scenario": "The map endpoint takes only a delivery id with no mention of a check that the caller is the customer for that delivery. An attacker who enumerates or guesses delivery ids can call the endpoint repeatedly and pull live GPS location and personal phone numbers for drivers and deliveries that aren't theirs.",
      "component": "Map endpoint",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "The map endpoint takes a delivery id and returns the driver location and phone number." }
      ],
      "asvs": ["V4.1.1"],
      "cwe": ["CWE-639"],
      "plainLanguage": "Someone could guess an order number and see a stranger's driver location and phone number.",
      "requirement": {
        "title": "Authorize map access to the delivery's own customer",
        "given": "A delivery id used to request driver location",
        "when": "The map endpoint is called",
        "then": "The system verifies the caller is the authenticated customer (or courier) tied to that specific delivery before returning any location or contact data"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Live map exposes the driver's personal phone number to every customer",
      "scenario": "The endpoint returns the driver's phone number alongside location data for every map view. A customer (or anyone who can reach the endpoint, per the threat above) gets the driver's personal phone number even though the live map feature only needs a position, exposing drivers to harassment or unwanted contact outside the app.",
      "component": "Map endpoint",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "The map endpoint takes a delivery id and returns the driver location and phone number." }
      ],
      "asvs": ["V8.3.4"],
      "cwe": ["CWE-200"],
      "plainLanguage": "The map shows the driver's real phone number, which isn't needed just to show where they are.",
      "requirement": {
        "title": "Minimize personal data returned by the map endpoint",
        "given": "A customer requests the live map for a delivery",
        "when": "The map endpoint responds",
        "then": "The response includes only the data required to render the map (e.g., masked/proxy contact, not the driver's real phone number)"
      }
    },
    {
      "stride": "Tampering",
      "title": "A driver's phone (or a spoofed client) can fake GPS location updates",
      "scenario": "Drivers' phones push GPS location every 10 seconds. There's no mention of server-side validation of these updates, so a compromised device, a rooted phone with a mock-location app, or a replayed/forged request could feed fake coordinates, misleading customers about where the delivery actually is or covering up a late/incorrect delivery.",
      "component": "GPS location sender",
      "likelihood": 3,
      "impact": 2,
      "evidence": [
        { "quote": "Delivery drivers’ phones send GPS location every 10 seconds." }
      ],
      "asvs": [],
      "cwe": ["CWE-345"],
      "plainLanguage": "A driver's app could send a fake location and the system would just believe it.",
      "requirement": {
        "title": "Validate and attribute location updates",
        "given": "A location update is received from a driver device",
        "when": "The update is stored and shown on the live map",
        "then": "The system authenticates the sending driver session and applies sanity checks (e.g., plausible speed/distance) before trusting the update"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Continuous 10-second tracking can be used to track a driver's movements long after a delivery ends",
      "scenario": "If a delivery id remains usable after the delivery completes, or the stream isn't cut off, anyone who retains the delivery id (e.g., a past customer, or an attacker from threat #1) can keep polling the map endpoint and build a precise, continuous movement history of the driver, enabling stalking.",
      "component": "Map endpoint",
      "likelihood": 2,
      "impact": 3,
      "evidence": [
        { "quote": "Customers see the driver on a live map." },
        { "quote": "Delivery drivers’ phones send GPS location every 10 seconds." }
      ],
      "asvs": ["V4.1.1"],
      "cwe": ["CWE-200"],
      "plainLanguage": "If old delivery links keep working, someone could keep tracking a driver's live position after the job is done.",
      "requirement": {
        "title": "Expire map/location access when a delivery completes",
        "given": "A delivery has been marked delivered or cancelled",
        "when": "The map endpoint is called with that delivery id afterward",
        "then": "The system returns no location data and denies further tracking access"
      }
    }
  ]
}
